derive_ns_retry_reason() {
    local val_exit="$1"
    local ns_mode="$2"
    case "$ns_mode" in
        structured)
            case "$val_exit" in
                5) printf 'JSON_PARSE_FAIL' ;;
                *) printf 'UNKNOWN' ;;
            esac ;;
        *)
            case "$val_exit" in
                2|3) printf 'NO_ISSUES_FOUND_TOO_THIN' ;;
                4)   printf 'OUTPUT_EMPTY' ;;
                *)   printf 'UNKNOWN' ;;
            esac ;;
    esac
